-- Database backstop for operational read-only archives. Financial settlements use their explicit commands.
CREATE TRIGGER archived_tasks_insert BEFORE INSERT ON tasks WHEN (SELECT is_archived FROM projects WHERE id=NEW.project_id)=1 BEGIN SELECT RAISE(ABORT,'PROJECT_ARCHIVED_READ_ONLY'); END;
CREATE TRIGGER archived_tasks_update BEFORE UPDATE ON tasks WHEN (SELECT is_archived FROM projects WHERE id=NEW.project_id)=1 BEGIN SELECT RAISE(ABORT,'PROJECT_ARCHIVED_READ_ONLY'); END;
CREATE TRIGGER archived_task_comments_insert BEFORE INSERT ON task_comments WHEN (SELECT is_archived FROM projects WHERE id=(SELECT project_id FROM tasks WHERE id=NEW.task_id))=1 BEGIN SELECT RAISE(ABORT,'PROJECT_ARCHIVED_READ_ONLY'); END;
CREATE TRIGGER archived_task_comments_update BEFORE UPDATE ON task_comments WHEN (SELECT is_archived FROM projects WHERE id=(SELECT project_id FROM tasks WHERE id=NEW.task_id))=1 BEGIN SELECT RAISE(ABORT,'PROJECT_ARCHIVED_READ_ONLY'); END;
CREATE TRIGGER archived_drawings_insert BEFORE INSERT ON drawings WHEN (SELECT is_archived FROM projects WHERE id=NEW.project_id)=1 BEGIN SELECT RAISE(ABORT,'PROJECT_ARCHIVED_READ_ONLY'); END;
CREATE TRIGGER archived_drawings_update BEFORE UPDATE ON drawings WHEN (SELECT is_archived FROM projects WHERE id=NEW.project_id)=1 BEGIN SELECT RAISE(ABORT,'PROJECT_ARCHIVED_READ_ONLY'); END;
CREATE TRIGGER archived_drawing_versions_insert BEFORE INSERT ON drawing_versions WHEN (SELECT is_archived FROM projects WHERE id=(SELECT project_id FROM drawings WHERE id=NEW.drawing_id))=1 BEGIN SELECT RAISE(ABORT,'PROJECT_ARCHIVED_READ_ONLY'); END;
CREATE TRIGGER archived_drawing_versions_update BEFORE UPDATE ON drawing_versions WHEN (SELECT is_archived FROM projects WHERE id=(SELECT project_id FROM drawings WHERE id=NEW.drawing_id))=1 BEGIN SELECT RAISE(ABORT,'PROJECT_ARCHIVED_READ_ONLY'); END;
CREATE TRIGGER archived_drawing_reviews_insert BEFORE INSERT ON drawing_reviews WHEN (SELECT is_archived FROM projects WHERE id=(SELECT d.project_id FROM drawing_versions v JOIN drawings d ON d.id=v.drawing_id WHERE v.id=NEW.version_id))=1 BEGIN SELECT RAISE(ABORT,'PROJECT_ARCHIVED_READ_ONLY'); END;
CREATE TRIGGER archived_drawing_reviews_update BEFORE UPDATE ON drawing_reviews WHEN (SELECT is_archived FROM projects WHERE id=(SELECT d.project_id FROM drawing_versions v JOIN drawings d ON d.id=v.drawing_id WHERE v.id=NEW.version_id))=1 BEGIN SELECT RAISE(ABORT,'PROJECT_ARCHIVED_READ_ONLY'); END;
