CREATE TRIGGER archived_project_updates_update BEFORE UPDATE ON project_updates WHEN (SELECT is_archived FROM projects WHERE id=NEW.project_id)=1 BEGIN SELECT RAISE(ABORT,'PROJECT_ARCHIVED_READ_ONLY'); END;
CREATE TRIGGER archived_update_versions_insert BEFORE INSERT ON update_versions WHEN (SELECT is_archived FROM projects WHERE id=(SELECT project_id FROM project_updates WHERE id=NEW.update_id))=1 BEGIN SELECT RAISE(ABORT,'PROJECT_ARCHIVED_READ_ONLY'); END;
CREATE TRIGGER archived_update_versions_update BEFORE UPDATE ON update_versions WHEN (SELECT is_archived FROM projects WHERE id=(SELECT project_id FROM project_updates WHERE id=NEW.update_id))=1 BEGIN SELECT RAISE(ABORT,'PROJECT_ARCHIVED_READ_ONLY'); END;
CREATE TRIGGER archived_update_attachments_insert BEFORE INSERT ON update_attachments WHEN (SELECT is_archived FROM projects WHERE id=(SELECT u.project_id FROM update_versions v JOIN project_updates u ON u.id=v.update_id WHERE v.id=NEW.version_id))=1 BEGIN SELECT RAISE(ABORT,'PROJECT_ARCHIVED_READ_ONLY'); END;
CREATE TRIGGER archived_update_attachments_update BEFORE UPDATE ON update_attachments WHEN (SELECT is_archived FROM projects WHERE id=(SELECT u.project_id FROM update_versions v JOIN project_updates u ON u.id=v.update_id WHERE v.id=NEW.version_id))=1 BEGIN SELECT RAISE(ABORT,'PROJECT_ARCHIVED_READ_ONLY'); END;
