-- Manual record categories exist without a mutating GET; no statutory status is inferred.
INSERT OR IGNORE INTO ksmart_milestones(id,org_id,project_id,milestone_type,tracking_label,created_at) SELECT 'ksm-sanction-'||id,org_id,id,'SANCTION','NOT_STARTED',created_at FROM projects WHERE is_archived=0;
INSERT OR IGNORE INTO ksmart_milestones(id,org_id,project_id,milestone_type,tracking_label,created_at) SELECT 'ksm-completion-'||id,org_id,id,'COMPLETION','NOT_STARTED',created_at FROM projects WHERE is_archived=0;
CREATE TRIGGER project_manual_record_categories AFTER INSERT ON projects WHEN NEW.is_archived=0 BEGIN
 INSERT INTO ksmart_milestones(id,org_id,project_id,milestone_type,tracking_label,created_at) VALUES('ksm-sanction-'||NEW.id,NEW.org_id,NEW.id,'SANCTION','NOT_STARTED',NEW.created_at);
 INSERT INTO ksmart_milestones(id,org_id,project_id,milestone_type,tracking_label,created_at) VALUES('ksm-completion-'||NEW.id,NEW.org_id,NEW.id,'COMPLETION','NOT_STARTED',NEW.created_at);
END;
